from functools import lru_cache as _cost_lru_cache

def _listing_cost_guard_matches(source):
    reviewed=LISTING_COST_REVIEWED_GUARD_SHA256.encode('ascii')
    return source.count(reviewed)==1 and hashlib.sha256(source.replace(reviewed,b'0'*64)).hexdigest()==LISTING_COST_REVIEWED_GUARD_SHA256

@_cost_lru_cache(maxsize=2)
def _listing_cost_cached_base_source(source,reviewed,parent):
    if b'\nLISTING_COST_BOOTSTRAP =' not in source:return source
    _require(reviewed==LISTING_COST_REVIEWED_GUARD_SHA256 and parent==LISTING_COST_PREVIOUS_GUARD_SHA256 and _listing_cost_guard_matches(source),'SUCCESSOR_GUARD_REVIEWED_BYTES_CHANGED')
    prefix,own=source.split(b'\nLISTING_COST_BOOTSTRAP =',1)
    previous=prefix+b'\nNFL_LISTING_BOOTSTRAP ='+own.split(b'\nNFL_LISTING_BOOTSTRAP =',1)[1]
    start=previous.index(b'\n_cost_original_listing_match=');end=previous.index(b'\nGUARD_MEMO_BOOTSTRAP =',start)
    previous=previous[:start]+previous[end:]
    start=previous.index(b'\n_cost_original_dfs_match=');end=previous.index(b'\ndef main() -> int:',start)
    previous=previous[:start]+previous[end:]
    dispatch=b'if exists_at("HEAD", LISTING_COST_POLICY_PATH):\n            code, report = _run_listing_cost_integrated(args.manifest, args.base)\n        elif exists_at("HEAD", NFL_LISTING_POLICY_PATH):'
    _require(previous.count(dispatch)==1,'PREVIOUS_GUARD_LOGIC_CHANGED')
    previous=previous.replace(dispatch,b'if exists_at("HEAD", NFL_LISTING_POLICY_PATH):',1)
    _require(hashlib.sha256(previous).hexdigest()==parent,'PREVIOUS_GUARD_LOGIC_CHANGED')
    return previous

def _listing_cost_base_source(source):
    _require(isinstance(source,bytes) and len(source)<=8*1024*1024,'SUCCESSOR_GUARD_REVIEWED_BYTES_CHANGED')
    return _listing_cost_cached_base_source(source,LISTING_COST_REVIEWED_GUARD_SHA256,LISTING_COST_PREVIOUS_GUARD_SHA256)
_listing_cost_base_source.cache_clear=_listing_cost_cached_base_source.cache_clear
_listing_cost_base_source.cache_info=_listing_cost_cached_base_source.cache_info

def _listing_cost_previous_source(path,source):
    if path==GUARD_PATH:return _listing_cost_base_source(source)
    info=LISTING_COST_SOURCE_RECONSTRUCTIONS.get(path)
    if info is None or hashlib.sha256(source).hexdigest()!=info['after_sha256']:return source
    value=json.loads(source)
    value['files']=[info['restore_rows'].get(row['path'],row) for row in value['files'] if row['path'] not in info['remove_paths']]
    value['sources']={key:row for key,row in value['sources'].items() if key not in info['remove_sources']}
    value.update(info['restore_fields'])
    result=(json.dumps(value,sort_keys=True,indent=2)+'\n').encode()
    _require(hashlib.sha256(result).hexdigest()==info['before_sha256'],'PREVIOUS_SOURCE_LOGIC_CHANGED')
    return result

_immutable_previous_cost_match=_listing_cost_guard_matches
_immutable_previous_cost_base=_listing_cost_base_source
def _listing_cost_guard_matches(source):return _immutable_previous_cost_match(_cost_immutable_base_source(source))
def _listing_cost_base_source(source):return _immutable_previous_cost_base(_cost_immutable_base_source(source))
_listing_cost_base_source.cache_clear=_immutable_previous_cost_base.cache_clear
_listing_cost_base_source.cache_info=_immutable_previous_cost_base.cache_info

