from functools import lru_cache as _scenario_lru_cache
@_scenario_lru_cache(maxsize=2)
def _nfl_scenario_guard_matches(source):
    reviewed=NFL_SCENARIO_REVIEWED_GUARD_SHA256.encode('ascii')
    return source.count(reviewed)==1 and hashlib.sha256(source.replace(reviewed,b'0'*64)).hexdigest()==NFL_SCENARIO_REVIEWED_GUARD_SHA256
@_scenario_lru_cache(maxsize=8)
def _nfl_scenario_base_source(source):
    if b'\nNFL_SCENARIO_BOOTSTRAP =' not in source:return source
    _require(_nfl_scenario_guard_matches(source),'SUCCESSOR_GUARD_REVIEWED_BYTES_CHANGED')
    previous=source.split(b'\nNFL_SCENARIO_BOOTSTRAP =',1)[0]+NFL_SCENARIO_PREVIOUS_TAIL
    _require(hashlib.sha256(previous).hexdigest()=='567db2a959bceef6136c7dc8adedbe753e4664282fecfec3d00328522e53e26f','PREVIOUS_GUARD_LOGIC_CHANGED')
    return previous

