def _ci_timing_guard_matches(source):
    reviewed=CI_TIMING_REVIEWED_GUARD_SHA256.encode('ascii')
    return source.count(reviewed)==1 and hashlib.sha256(source.replace(reviewed,b'0'*64)).hexdigest()==CI_TIMING_REVIEWED_GUARD_SHA256
from functools import lru_cache as _ci_timing_lru_cache
@_ci_timing_lru_cache(maxsize=2)
def _ci_timing_base_source(source):
    if b'\nCI_TIMING_BOOTSTRAP =' not in source:return source
    _require(_ci_timing_guard_matches(source),'SUCCESSOR_GUARD_REVIEWED_BYTES_CHANGED')
    previous=source.split(b'\nCI_TIMING_BOOTSTRAP =',1)[0]+CI_TIMING_PREVIOUS_TAIL
    _require(hashlib.sha256(previous).hexdigest()=='ede96751a4d40f12d7be0be6718e1adad627da56ddc033e33d8fea35f5c61bad','PREVIOUS_GUARD_LOGIC_CHANGED')
    return previous

