def _owner_guard_matches(source):
    reviewed = OWNER_REVIEWED_GUARD_SHA256.encode('ascii')
    return source.count(reviewed) == 1 and hashlib.sha256(source.replace(reviewed, b'0'*64)).hexdigest() == OWNER_REVIEWED_GUARD_SHA256

def _owner_base_source(source):
    if b'\nNCAAF_OWNER_BOOTSTRAP =' not in source: return source
    _require(_owner_guard_matches(source), 'SUCCESSOR_GUARD_REVIEWED_BYTES_CHANGED')
    previous = source.split(b'\nNCAAF_OWNER_BOOTSTRAP =', 1)[0] + OWNER_PREVIOUS_TAIL
    _require(hashlib.sha256(previous).hexdigest() == '1639ccad41c0943799b30aaf6f8c0f08c08aaef96293408d147a919537a6406b', 'PREVIOUS_GUARD_LOGIC_CHANGED')
    return previous

_owner_peel = _owner_base_source

# Install before inherited bootstrap initialization; its exact parent remains
# available even while it reads this explicitly bound successor file.
_owner_boot_cloud_match = _cloud_guard_matches
_owner_boot_cloud_peel = _cloud_peel_exact_guard
_owner_boot_discovery_match = _discovery_guard_matches
_owner_boot_discovery_parent = _discovery_parent_guard_source
def _cloud_guard_matches(source):
    return _owner_boot_cloud_match(_owner_peel(source))
def _cloud_peel_exact_guard(source):
    return _owner_boot_cloud_peel(_owner_peel(source))

def _discovery_guard_matches(source):
    return _owner_boot_discovery_match(_owner_peel(source))
def _discovery_parent_guard_source(source):
    return _owner_boot_discovery_parent(_owner_peel(source))
_nfl_owner_early_owner_match = _owner_guard_matches
_nfl_owner_early_owner_peel = _owner_base_source
def _owner_guard_matches(source):
    return _nfl_owner_early_owner_match(_nfl_owner_peel(source))
def _owner_base_source(source):
    return _nfl_owner_early_owner_peel(_nfl_owner_peel(source))
_owner_peel = _owner_base_source


