# Parse the exact immutable reconstruction subject only on the matching profile
# path/hash. Live policy validation separately rereads and verifies declarations.
def _listing_cost_previous_source(path,source):
    if path==GUARD_PATH:return _listing_cost_base_source(source)
    if path!='scripts/ci_test_file_costs_v1.json' or hashlib.sha256(source).hexdigest()!=COST_IMMUTABLE_PROFILE_AFTER_SHA256:return source
    info=json.loads(COST_IMMUTABLE_RECONSTRUCTION_JSON)
    value=json.loads(source)
    value['files']=[info['restore_rows'].get(row['path'],row) for row in value['files'] if row['path'] not in info['remove_paths']]
    value['sources']={key:row for key,row in value['sources'].items() if key not in info['remove_sources']}
    value.update(info['restore_fields'])
    result=(json.dumps(value,sort_keys=True,indent=2)+'\n').encode()
    _require(hashlib.sha256(result).hexdigest()==info['before_sha256'],'PREVIOUS_SOURCE_LOGIC_CHANGED')
    return result
